problems.solution:
Recursivitatea curăță întâi coada listei. Când revine la un nod, toate valorile de după el apar o singură dată; dacă valoarea nodului e printre ele, nodul nu e ultima apariție și se șterge. Complexitate O(n²) pentru lista simplă, suficient aici.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    int val;
    struct node *next;
} TNode, *TList;

int contains(TList l, int x) {
    for (; l; l = l->next)
        if (l->val == x) return 1;
    return 0;
}

/* removes duplicates, keeping the last occurrence of each value */
TList dedup(TList l) {
    if (!l) return NULL;
    l->next = dedup(l->next);
    if (contains(l->next, l->val)) {
        TList rest = l->next;
        free(l);
        return rest;
    }
    return l;
}

int main(void) {
    int n;
    TList head = NULL, tail = NULL;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) {
        TList c = (TList)malloc(sizeof(TNode));
        scanf("%d", &c->val);
        c->next = NULL;
        if (tail) tail->next = c; else head = c;
        tail = c;
    }
    head = dedup(head);
    if (!head) puts("vida");
    for (TList p = head; p; p = p->next) printf("%d%c", p->val, p->next ? ' ' : '\n');
    while (head) { TList p = head->next; free(head); head = p; }
    return 0;
}
```

