problems.solution:
Cu prima listă crescătoare și a doua descrescătoare, fiecare pas elimină cel puțin un element care nu mai poate face parte din vreo pereche: dacă x + y < k, x e prea mic pentru toți y rămași; dacă e prea mare, y e prea mare pentru toți x rămași. O(n + m). Suma se calculează în `long long`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    int val;
    struct node *next;
} TNode, *TList;

TList readList(int n) {
    TList head = NULL, tail = NULL;
    for (int i = 0; i < n; i++) {
        TList c = (TList)malloc(sizeof(TNode));
        scanf("%d", &c->val);
        c->next = NULL;
        if (tail) tail->next = c; else head = c;
        tail = c;
    }
    return head;
}

TList reverse(TList l) {
    TList prev = NULL;
    while (l) {
        TList nx = l->next;
        l->next = prev;
        prev = l;
        l = nx;
    }
    return prev;
}

int count(TList l1, TList l2, long long k) {
    int c = 0;
    while (l1 && l2) {
        long long s = (long long)l1->val + l2->val;
        if (s == k) { c++; l1 = l1->next; l2 = l2->next; }
        else if (s < k) l1 = l1->next;
        else l2 = l2->next;
    }
    return c;
}

void freeList(TList l) {
    while (l) { TList p = l->next; free(l); l = p; }
}

int main(void) {
    int n, m;
    long long k;
    if (scanf("%d %d %lld", &n, &m, &k) != 3) return 0;
    TList a = readList(n), b = reverse(readList(m));
    printf("%d\n", count(a, b, k));
    freeList(a);
    freeList(b);
    return 0;
}
```

