problems.solution:
În inordine cheile vin crescător, deci perechea (nod, succesor) e perechea de noduri vizitate consecutiv. Se păstrează diferența maximă; cu `>` strict, la egalitate rămâne primul nod, cel cu cheia mai mică. Nodul cu cheia maximă are diferența 0, care contează doar dacă arborele are un singur nod.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct tnode {
    int key;
    struct tnode *left, *right;
} TNode;

TNode *insert(TNode *t, int k) {
    if (!t) {
        t = (TNode *)malloc(sizeof(TNode));
        t->key = k;
        t->left = t->right = NULL;
    } else if (k < t->key) t->left = insert(t->left, k);
    else if (k > t->key) t->right = insert(t->right, k);
    return t;
}

TNode *prev = NULL;
long long bestDiff = -1;
int bestKey;

void inorder(TNode *t) {
    if (!t) return;
    inorder(t->left);
    if (prev) {
        long long d = (long long)t->key - prev->key;
        if (d > bestDiff) { bestDiff = d; bestKey = prev->key; }
    }
    prev = t;
    inorder(t->right);
}

void destroy(TNode *t) {
    if (!t) return;
    destroy(t->left);
    destroy(t->right);
    free(t);
}

int main(void) {
    int n;
    TNode *root = NULL;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) {
        int k;
        scanf("%d", &k);
        root = insert(root, k);
    }
    inorder(root);
    if (bestDiff < 0) { /* a single node: no successor, difference 0 */
        bestDiff = 0;
        bestKey = prev->key;
    }
    printf("%d %lld\n", bestKey, bestDiff);
    destroy(root);
    return 0;
}
```

