problems.solution:
O singură parcurgere în postordine: fiecare nod află câte valori y are în stânga și în dreapta, adună propria valoare și compară cu t. O(n).

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct tnode {
    int val;
    struct tnode *left, *right;
} TNode;

TNode *build(int n) {
    int *v = (int *)malloc((n + 1) * sizeof(int)), *l = (int *)malloc((n + 1) * sizeof(int)), *r = (int *)malloc((n + 1) * sizeof(int));
    TNode **p = (TNode **)malloc((n + 1) * sizeof(TNode *));
    p[0] = NULL;
    for (int i = 1; i <= n; i++) {
        scanf("%d %d %d", &v[i], &l[i], &r[i]);
        p[i] = (TNode *)malloc(sizeof(TNode));
    }
    for (int i = 1; i <= n; i++) {
        p[i]->val = v[i];
        p[i]->left = p[l[i]];
        p[i]->right = p[r[i]];
    }
    TNode *root = p[1];
    free(v); free(l); free(r); free(p);
    return root;
}

void destroy(TNode *t) {
    if (!t) return;
    destroy(t->left);
    destroy(t->right);
    free(t);
}

int result = 0;

int countY(TNode *t, int th, int y) {
    if (!t) return 0;
    int c = countY(t->left, th, y) + countY(t->right, th, y) + (t->val == y);
    if (c > th) result++;
    return c;
}

int Numara(TNode *root, int th, int y) {
    result = 0;
    countY(root, th, y);
    return result;
}

int main(void) {
    int n, th, y;
    if (scanf("%d", &n) != 1) return 0;
    TNode *root = build(n);
    scanf("%d %d", &th, &y);
    printf("%d\n", Numara(root, th, y));
    destroy(root);
    return 0;
}
```

