problems.solution:
Coada dă nodurile în ordinea nivelurilor, iar pe același nivel de la stânga la dreapta, pentru că fiii stângi intră înaintea celor drepți. Fiecare listă păstrează și un pointer la ultimul nod, deci adăugarea e O(1).

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct tnode {
    int val;
    struct tnode *left, *right;
} TNode;

TNode *build(int n) {
    int *v = (int *)malloc((n + 1) * sizeof(int)), *l = (int *)malloc((n + 1) * sizeof(int)), *r = (int *)malloc((n + 1) * sizeof(int));
    TNode **p = (TNode **)malloc((n + 1) * sizeof(TNode *));
    p[0] = NULL;
    for (int i = 1; i <= n; i++) {
        scanf("%d %d %d", &v[i], &l[i], &r[i]);
        p[i] = (TNode *)malloc(sizeof(TNode));
    }
    for (int i = 1; i <= n; i++) {
        p[i]->val = v[i];
        p[i]->left = p[l[i]];
        p[i]->right = p[r[i]];
    }
    TNode *root = p[1];
    free(v); free(l); free(r); free(p);
    return root;
}

void destroy(TNode *t) {
    if (!t) return;
    destroy(t->left);
    destroy(t->right);
    free(t);
}

typedef struct lnode {
    int val;
    struct lnode *next;
} LNode;

/* appends to the list of a level, keeping a pointer to its last node */
void append(LNode **head, LNode **tail, int v) {
    LNode *c = (LNode *)malloc(sizeof(LNode));
    c->val = v;
    c->next = NULL;
    if (*tail) (*tail)->next = c; else *head = c;
    *tail = c;
}

int Transf(TNode *root, int n, LNode ***levels) {
    LNode **head = (LNode **)calloc(n + 1, sizeof(LNode *)), **tail = (LNode **)calloc(n + 1, sizeof(LNode *));
    TNode **q = (TNode **)malloc(n * sizeof(TNode *));
    int *lv = (int *)malloc(n * sizeof(int));
    int b = 0, e = 0, depth = 0;
    q[e] = root; lv[e++] = 1;
    while (b < e) {
        TNode *t = q[b];
        int l = lv[b++];
        if (l > depth) depth = l;
        append(&head[l], &tail[l], t->val);
        if (t->left) { q[e] = t->left; lv[e++] = l + 1; }
        if (t->right) { q[e] = t->right; lv[e++] = l + 1; }
    }
    free(q); free(lv); free(tail);
    *levels = head;
    return depth;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    TNode *root = build(n);
    LNode **levels;
    int depth = Transf(root, n, &levels);
    for (int k = 1; k <= depth; k++) {
        for (LNode *p = levels[k]; p; ) {
            LNode *nx = p->next;
            printf("%d%c", p->val, nx ? ' ' : '\n');
            free(p);
            p = nx;
        }
    }
    free(levels);
    destroy(root);
    return 0;
}
