#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int *v;
    int n, cap;
} Heap;

void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }

void siftUp(Heap *h, int k) {
    while (k > 0 && h->v[(k - 1) / 2] < h->v[k]) {
        swap(&h->v[(k - 1) / 2], &h->v[k]);
        k = (k - 1) / 2;
    }
}

void siftDown(Heap *h, int k) {
    for (;;) {
        int c = 2 * k + 1;
        if (c >= h->n) return;
        if (c + 1 < h->n && h->v[c + 1] > h->v[c]) c++;
        if (h->v[c] <= h->v[k]) return;
        swap(&h->v[c], &h->v[k]);
        k = c;
    }
}

void insert(Heap *h, int x) {
    if (h->n == h->cap) {
        h->cap = h->cap ? 2 * h->cap : 16;
        h->v = (int *)realloc(h->v, h->cap * sizeof(int));
    }
    h->v[h->n++] = x;
    siftUp(h, h->n - 1);
}

int extractMax(Heap *h) {
    int m = h->v[0];
    h->v[0] = h->v[--h->n];
    siftDown(h, 0);
    return m;
}

