Rezolvarea coliziunilor prin înlănțuire: cheile cu același h(k) stau în aceeași listă; inserarea la început e O(1), dar căutarea duplicatului parcurge lista.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    int key;
    struct node *next;
} TNode;

int main(void) {
    int m, n;
    if (scanf("%d %d", &m, &n) != 2) return 0;
    TNode **b = (TNode **)calloc(m, sizeof(TNode *));
    for (int i = 0; i < n; i++) {
        int k;
        scanf("%d", &k);
        int h = k % m, found = 0;
        for (TNode *p = b[h]; p; p = p->next)
            if (p->key == k) { found = 1; break; }
        if (found) continue;
        TNode *c = (TNode *)malloc(sizeof(TNode));
        c->key = k;
        c->next = b[h];
        b[h] = c;
    }
    for (int i = 0; i < m; i++) {
        printf("%d:", i);
        for (TNode *p = b[i]; p;) {
            TNode *nx = p->next;
            printf(" %d", p->key);
            free(p);
            p = nx;
        }
        printf("\n");
    }
    free(b);
    return 0;
}
